## 9. Query Patterns

### Basic CRUD

```typescript
// CREATE
const { data, error } = await supabase
  .from('orders')
  .insert({ order_id: 'new_123', customer_email: 'test@test.com' })
  .select()
  .single();

// READ (single)
const { data, error } = await supabase
  .from('orders')
  .select('*')
  .eq('order_id', 'order_123')
  .single();

// READ (list with filter)
const { data, error } = await supabase
  .from('orders')
  .select('*')
  .eq('status', 'pending')
  .order('created_at', { ascending: false })
  .limit(20);

// UPDATE
const { data, error } = await supabase
  .from('orders')
  .update({ status: 'completed' })
  .eq('order_id', 'order_123')
  .select()
  .single();

// DELETE
const { error } = await supabase
  .from('orders')
  .delete()
  .eq('order_id', 'order_123');
```

### Upsert Pattern

```typescript
// Insert or update based on primary key
const { data, error } = await supabase
  .from('orders')
  .upsert(
    {
      order_id: 'order_123', // PK for conflict detection
      customer_email: 'updated@test.com',
      total: 150,
    },
    { onConflict: 'order_id' }
  )
  .select()
  .single();
```

### Batch Insert

```typescript
// Insert multiple records
const tickets = [
  { order_id: 'order_123', ticket_type: 'VIP', status: 'live' },
  { order_id: 'order_123', ticket_type: 'VIP', status: 'live' },
  { order_id: 'order_123', ticket_type: 'Regular', status: 'live' },
];

const { data, error } = await supabase
  .from('tickets')
  .insert(tickets)
  .select();
```

### Avoid N+1 Queries

```typescript
// ❌ BAD: N+1 problem
const orders = await fetchOrders();
for (const order of orders) {
  const tickets = await fetchTickets(order.order_id); // N queries!
  order.tickets = tickets;
}

// ✅ GOOD: Batch fetch
const orders = await fetchOrders();
const orderIds = orders.map((o) => o.order_id);

const { data: allTickets } = await supabase
  .from('tickets')
  .select('*')
  .in('order_id', orderIds); // 1 query!

// Group by order_id
const ticketsByOrder = allTickets.reduce((acc, ticket) => {
  if (!acc[ticket.order_id]) acc[ticket.order_id] = [];
  acc[ticket.order_id].push(ticket);
  return acc;
}, {} as Record<string, Ticket[]>);

// Attach to orders
orders.forEach((order) => {
  order.tickets = ticketsByOrder[order.order_id] || [];
});
```

### Aggregation Queries

```sql
-- Count by status
SELECT status, COUNT(*) as count
FROM tickets
GROUP BY status;

-- Sum revenue by event
SELECT 
  event_id,
  event_name,
  SUM(total_paid) as total_revenue,
  COUNT(*) as order_count
FROM orders
WHERE payment_status = 'paid'
GROUP BY event_id, event_name;

-- Tickets with order info
SELECT 
  t.*,
  o.event_name,
  o.contact_email
FROM tickets t
JOIN orders o ON t.order_id = o.order_id
WHERE t.status = 'live';
```

