.gte('col', 10)        // Greater or equal
.lte('col', 10)        // Less or equal
.like('col', '%val%')  // Pattern match
.ilike('col', '%val%') // Case-insensitive pattern
.in('col', [1, 2, 3])  // In array
.is('col', null)       // Is null
```

