## 6. Cart Logic

### Cart Store Structure

```typescript
// src/store/useCartStore.ts

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

export interface CartItem {
  id: string;                    // Composite key
  productId: number;
  variationId?: number;
  name: string;
  slug: string;
  price: number;                 // Unit price in cents
  regularPrice: number;
  quantity: number;
  image?: string;
  attributes?: Record<string, string>;  // e.g., { color: 'Red', size: 'Large' }
  customFields?: Record<string, string>;
}

interface CartState {
  items: CartItem[];
  hasHydrated: boolean;

  // Actions
  addItem: (item: Omit<CartItem, 'id'>) => void;
  removeItem: (id: string) => void;
  updateQuantity: (id: string, quantity: number) => void;
  incrementQuantity: (id: string) => void;
  decrementQuantity: (id: string) => void;
  clearCart: () => void;
  setHasHydrated: (value: boolean) => void;
}

// Generate composite key for cart items
const generateCartItemId = (
  productId: number,
  variationId?: number,
  attributes?: Record<string, string>
): string => {
  let id = `${productId}`;
  if (variationId) id += `-${variationId}`;
  if (attributes) id += `-${JSON.stringify(attributes)}`;
  return id;
};

export const useCartStore = create<CartState>()(
  persist(
    (set, get) => ({
      items: [],
      hasHydrated: false,

      addItem: (item) => {
        const id = generateCartItemId(
          item.productId,
          item.variationId,
          item.attributes
        );

        set((state) => {
          const existingIndex = state.items.findIndex((i) => i.id === id);

          if (existingIndex >= 0) {
            // Update quantity of existing item
            const newItems = [...state.items];
            newItems[existingIndex] = {
              ...newItems[existingIndex],
              quantity: newItems[existingIndex].quantity + item.quantity,
            };
            return { items: newItems };
          }

          // Add new item
          return {
            items: [...state.items, { ...item, id }],
          };
        });
      },

      removeItem: (id) =>
        set((state) => ({
          items: state.items.filter((item) => item.id !== id),
        })),

      updateQuantity: (id, quantity) =>
        set((state) => {
          if (quantity <= 0) {
            return { items: state.items.filter((item) => item.id !== id) };
          }
          return {
            items: state.items.map((item) =>
              item.id === id ? { ...item, quantity } : item
            ),
          };
        }),

      incrementQuantity: (id) => {
        const item = get().items.find((i) => i.id === id);
        if (item) {
          get().updateQuantity(id, item.quantity + 1);
        }
      },

      decrementQuantity: (id) => {
        const item = get().items.find((i) => i.id === id);
        if (item && item.quantity > 1) {
          get().updateQuantity(id, item.quantity - 1);
        } else if (item) {
          get().removeItem(id);
        }
      },

      clearCart: () => set({ items: [] }),
      setHasHydrated: (hasHydrated) => set({ hasHydrated }),
    }),
    {
      name: 'cart-storage',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ items: state.items }),
      onRehydrateStorage: () => (state) => {
        state?.setHasHydrated(true);
      },
    }
  )
);

// Selectors
export const selectCartItems = (state: CartState) => state.items;
export const selectCartItemCount = (state: CartState) =>
  state.items.reduce((sum, item) => sum + item.quantity, 0);
export const selectCartSubtotal = (state: CartState) =>
  state.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
export const selectHasHydrated = (state: CartState) => state.hasHydrated;
